<script setup lang="ts">
import{ref,onBeforeUnmount}from'vue';import{useAccessStore}from'@vben/stores';import VideoPreview from'./VideoPreview.vue';
const props=defineProps<{modelValue?:string;disabled?:boolean}>();const emit=defineEmits<{ 'update:modelValue':[value:string]; busy:[value:boolean] }>();const access=useAccessStore();const progress=ref(0),busy=ref(false),error=ref(''),input=ref<HTMLInputElement>();let request:XMLHttpRequest|null=null;
function cancel(){const old=request;request=null;old?.abort();busy.value=false;emit('busy',false)}
function choose(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(!/\.mp4$/i.test(file.name)||file.size>50*1024*1024){error.value='请选择不超过 50MB 的 MP4 视频';return}cancel();busy.value=true;emit('busy',true);error.value='';progress.value=0;const xhr=new XMLHttpRequest();request=xhr;xhr.open('POST','/api/files/upload/video');xhr.setRequestHeader('Authorization',`Bearer ${access.accessToken}`);xhr.timeout=180000;xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=Math.round(e.loaded/e.total*100)};xhr.onload=()=>{if(request!==xhr)return;try{const result=JSON.parse(xhr.responseText);if(xhr.status>=400||result.code!==0)throw Error(result.message||'上传失败');emit('update:modelValue',result.data.url)}catch(e){error.value=e instanceof Error?e.message:'上传失败'}finally{cancel();if(input.value)input.value.value=''}};xhr.onerror=xhr.ontimeout=()=>{if(request===xhr){error.value='上传失败，请检查网络后重新选择文件。';cancel()}};const form=new FormData();form.append('file',file);xhr.send(form)}onBeforeUnmount(cancel);
</script><template><section class="video-upload"><input ref="input" type="file" accept="video/mp4,.mp4" :disabled="disabled||busy" aria-label="选择教学视频" @change="choose"/><p>MP4 · 最大 50MB · 建议 H.264 + AAC；请同时提供文字步骤。视频与项目一起审核。</p><p>仅上传原创或已获授权的内容，不包含未经同意的人像、声音与个人信息。</p><div v-if="busy" role="status"><progress :value="progress" max="100"/> {{progress}}% <button @click="cancel">取消上传</button></div><p v-if="error" role="alert" class="error">{{error}}</p><VideoPreview v-if="modelValue&&!busy" :src="modelValue"/><button v-if="modelValue&&!disabled&&!busy" class="remove" @click="emit('update:modelValue','')">移除视频</button></section></template><style scoped>.video-upload{width:100%;padding:20px;border:1px dashed var(--el-border-color);border-radius:14px;background:var(--el-fill-color-extra-light)}p{font-size:12px;line-height:1.8;color:var(--el-text-color-regular);margin:10px 0}button{padding:6px 12px;color:var(--el-color-primary)}.error{color:var(--el-color-danger)}progress{accent-color:var(--el-color-primary);width:220px}.remove{margin-top:12px}</style>
